@startuml

class House {
  + address : string
  + buildingMaterial : string
}

class Basement {
  + name : string
  + size : string
}

class EarthBasement extends Basement {
  + humidityLevel : float
}

class ConcreteBasement extends Basement {}

class SemiDetachedHouse extends House {
  + hasGarden : boolean
  + windowCount : int
}

class Carport {
  + isDoubleCarport : boolean
  + hasFlatRoof : boolean
}

class Garage {
  + hasAutomaticDoor : boolean
}

class Company {
  + name : string
  + address : string
}

class JobLog {
  + hours : int
  + agreedPrice : double
}

House "0..1" -- "0..1" Basement
House "1" -- "0..*" JobLog
Company "1" -- "0..*" JobLog
SemiDetachedHouse "1" -- "2" Carport
SemiDetachedHouse "1" -- "1" Garage

@enduml

